# find connected components of 2s
import sys
sys.setrecursionlimit(100000)
seen=[[False]*W for _ in range(H)]
comps=[]
for r in range(H):
    for c in range(W):
        if g[r][c]==2 and not seen[r][c]:
            stack=[(r,c)]; seen[r][c]=True; cells=[]
            while stack:
                x,y=stack.pop(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<H and 0<=ny<W and g[nx][ny]==2 and not seen[nx][ny]:
                        seen[nx][ny]=True; stack.append((nx,ny))
            comps.append(cells)
print(len(comps), [len(c) for c in comps])
rows4=[4,11]; cols4=[0,5,24]
out4=[row[:] for row in g]
for comp in comps:
    if any(r in rows4 or c in cols4 for r,c in comp):
        for r,c in comp: out4[r][c]=1
for r in rows4: out4[r]=[1]*W
for c in cols4:
    for r in range(H): out4[r][c]=1
print('\n'.join(' '.join(map(str,row)) for row in out4))

